function renderToString(string, prefix) {
    try {
        let trim = str => String(str || '').replace(/`|~/g, ""),
            json = JSON.parse(string),
            searchKey = trim(json.t),
            href = `https://www.moedict.tw/${prefix||""}${searchKey}`,
            searchBrowser = `<a href="${href}">網頁打開</a>`,
            html = [];
        for (item of json.h) {
            html.push(`<h1>${searchKey}</h1>`), item.p && html.push(`<span>[ ${item.p.replace(/（.*?）/,"")} ]</span>`);
            if (item.d == null) continue;
            for (define of item.d) {
                html.push("<li>"), define.f && html.push(`<span class="def">${trim(define.f)}</span>`), Object.values(define).filter(v => v instanceof Array).forEach(array => array.forEach(ele => html.push(`<div>${trim(ele)}</div>`))), html.push("</li>")
            }
        }
        return html.join("\n") + searchBrowser
    } catch (e) {
        return `${string}\n${e}`
    }
};
